#!/usr/bin/env bash
# Doc dev : la commande d'installation de chaque dépendance, au chapitre où elle sert ; garde
# check-doc-installs dans pnpm check ; tsx retiré. Relance pnpm install (hors ligne). Pas de migration.
# Prérequis : apply-fix-arbre-profondeur.sh. Arrête pnpm dev avant.
# Usage (racine du repo) : bash apply-docs-installer.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" 2>/dev/null | grep -qF "Chaque dépendance, installée une fois"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "construireArbre" "apps/web/src/features/docs/ui/Arbre.tsx" 2>/dev/null || { echo "lancez d'abord apply-fix-arbre-profondeur.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/la-carte-du-systeme.mdx" "apps/web/content/docs/dev/api/valider-l-entree.mdx" "apps/web/content/docs/dev/auth/la-session-dans-le-backend.mdx" "apps/web/content/docs/dev/auth/le-mot-de-passe-oublie.mdx" "apps/web/content/docs/dev/auth/se-connecter.mdx" "apps/web/content/docs/dev/configuration/next-config.mdx" "apps/web/content/docs/dev/contenu/le-registre-et-l-editeur.mdx" "apps/web/content/docs/dev/contenu/le-texte-riche.mdx" "apps/web/content/docs/dev/demarrer/organiser-le-depot.mdx" "apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx" "apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx" "apps/web/content/docs/dev/envois/les-formulaires-de-lot.mdx" "apps/web/content/docs/dev/envois/les-photos-d-iphone.mdx" "apps/web/content/docs/dev/finder/agir-sur-les-fichiers.mdx" "apps/web/content/docs/dev/finder/l-arbre-et-la-grille.mdx" "apps/web/content/docs/dev/finder/un-composant-des-adaptateurs.mdx" "apps/web/content/docs/dev/formulaires/react-hook-form.mdx" "apps/web/content/docs/dev/front/styles.mdx" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/content/docs/dev/membres/demandes.mdx" "apps/web/content/docs/dev/membres/documents-des-membres.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "apps/web/content/docs/dev/moteur-doc/du-code-cite-au-code-montre.mdx" "apps/web/content/docs/dev/moteur-doc/relier-les-chapitres.mdx" "apps/web/content/docs/dev/moteur-doc/une-page-du-fichier-a-l-ecran.mdx" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx" "apps/web/content/docs/dev/stockage/servir-un-fichier.mdx" "apps/web/content/docs/dev/stockage/signer-un-envoi.mdx" "apps/web/content/docs/dev/stockage/un-stockage-objet.mdx" "e2e/docs-demarrer.spec.ts" "package.json" "pnpm-lock.yaml")
CREATED=("scripts/check-doc-installs.mjs")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Chaque dépendance, installée une fois" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

